// ── Auth Check ──────────────────────────────────────────────────
const MCP_API_KEY = 'test-key-123'; // Cambia en producción
const authHeader  = $input.first().headers?.authorization || '';
const token       = authHeader.replace('Bearer ', '').trim();

if (token !== MCP_API_KEY) {
  return [{ json: { _auth_error: true, status: 401, error: 'Unauthorized' } }];
}

const body    = $input.first().json;
const action  = body.action  || '';
const context = body.context || {};
const sql     = body.sql     || '';

// ═══════════════════════════════════════════════════════════════
// TENANT ROUTER: resuelve qué "base de datos" usar según contexto
// ═══════════════════════════════════════════════════════════════
function resolveTenant(ctx) {
  const key = `${(ctx.contextName || '').toLowerCase()}_${(ctx.country || 'EC').toUpperCase()}`;

  const tenants = {
    // Agrega aquí tus tenants reales
    // 'distribuidora_abc_EC': { name: 'ABC Ecuador', schema: 'mobilvendor_abc_ec' },
  };

  return tenants[key] || {
    name:   ctx.contextName || 'Demo',
    schema: 'mobilvendor_demo',
    country: ctx.country || 'EC'
  };
}

const tenant = resolveTenant(context);

// ═══════════════════════════════════════════════════════════════
// ACTION: schema → retorna estructura de tablas disponibles
// ═══════════════════════════════════════════════════════════════
if (action === 'schema') {

  // Schema MOCK para pruebas
  // En producción, aquí consultarías INFORMATION_SCHEMA de la DB real
  const mockSchema = `
pagos_proveedores(id INT, id_proveedor INT, monto DECIMAL, fecha_pago DATE, estado VARCHAR, referencia VARCHAR, concepto VARCHAR)
proveedores(id INT, nombre_proveedor VARCHAR, ruc VARCHAR, telefono VARCHAR, email VARCHAR, categoria VARCHAR)
facturas(id INT, numero_factura VARCHAR, id_cliente INT, subtotal DECIMAL, iva DECIMAL, total DECIMAL, fecha_emision DATE, estado VARCHAR)
clientes(id INT, nombre VARCHAR, ruc_cedula VARCHAR, email VARCHAR, telefono VARCHAR, ciudad VARCHAR, pais VARCHAR)
pedidos(id INT, id_cliente INT, id_vendedor INT, fecha_pedido DATE, estado VARCHAR, total DECIMAL, observaciones VARCHAR)
detalle_pedidos(id INT, id_pedido INT, id_producto INT, cantidad INT, precio_unitario DECIMAL, descuento DECIMAL)
productos(id INT, codigo VARCHAR, nombre VARCHAR, categoria VARCHAR, precio DECIMAL, stock INT, unidad VARCHAR)
vendedores(id INT, nombre VARCHAR, zona VARCHAR, meta_mensual DECIMAL, ventas_mes DECIMAL)
`.trim();

  return [{
    json: {
      success: true,
      action:  'schema',
      tenant:  tenant.name,
      schema:  mockSchema,
      dialect: 'MySQL'
    }
  }];
}

// ═══════════════════════════════════════════════════════════════
// ACTION: query → valida SQL y ejecuta contra datos MOCK
// ═══════════════════════════════════════════════════════════════
if (action === 'query') {

  // Validación de seguridad: SOLO SELECT
  const sqlUpper = sql.trim().toUpperCase();
  const forbidden = ['INSERT', 'UPDATE', 'DELETE', 'DROP', 'ALTER', 
                     'TRUNCATE', 'CREATE', 'EXEC', 'GRANT', 'REVOKE'];

  if (!sqlUpper.startsWith('SELECT')) {
    return [{ json: {
      success: false,
      error:   'Solo se permiten consultas SELECT de lectura',
      tenant:  tenant.name
    }}];
  }

  for (const kw of forbidden) {
    if (sqlUpper.includes(kw)) {
      return [{ json: {
        success: false,
        error:   `Operación no permitida: ${kw}`,
        tenant:  tenant.name
      }}];
    }
  }

  // ── DATOS MOCK por tabla detectada en el SQL ──────────────────
  const mockData = {
    pagos_proveedores: [
      { proveedor: 'Distribuidora XYZ S.A.', ruc: '0990123456001', monto: 2450.00, fecha_pago: '2026-03-10', estado: 'Pagado', referencia: 'TRF-001234', concepto: 'Compra mercadería marzo' },
      { proveedor: 'Importaciones ABC Cía.', ruc: '1790234567001', monto: 1890.50, fecha_pago: '2026-03-08', estado: 'Pagado', referencia: 'TRF-001220', concepto: 'Insumos de oficina' },
      { proveedor: 'Logística del Sur',      ruc: '0910345678001', monto: 650.00,  fecha_pago: '2026-03-05', estado: 'Pagado', referencia: 'TRF-001198', concepto: 'Servicio de transporte' },
      { proveedor: 'Tech Solutions EC',      ruc: '1701456789001', monto: 3200.00, fecha_pago: '2026-03-03', estado: 'Pendiente', referencia: 'TRF-001180', concepto: 'Licencias software' },
      { proveedor: 'Proveedor Local SRL',    ruc: '0920567890001', monto: 780.25,  fecha_pago: '2026-02-28', estado: 'Pagado', referencia: 'TRF-001165', concepto: 'Material de empaque' }
    ],
    facturas: [
      { numero_factura: 'F001-0045231', cliente: 'Cliente A S.A.',  total: 1250.00, fecha_emision: '2026-03-11', estado: 'Emitida' },
      { numero_factura: 'F001-0045230', cliente: 'Cliente B Cía.',  total: 890.75,  fecha_emision: '2026-03-10', estado: 'Cobrada' },
      { numero_factura: 'F001-0045229', cliente: 'Cliente C Ltda.', total: 3400.00, fecha_emision: '2026-03-09', estado: 'Pendiente' },
      { numero_factura: 'F001-0045228', cliente: 'Cliente D S.A.',  total: 567.50,  fecha_emision: '2026-03-08', estado: 'Emitida' },
    ],
    pedidos: [
      { id: 1001, cliente: 'Cliente A', fecha_pedido: '2026-03-11', estado: 'Entregado', total: 1250.00 },
      { id: 1002, cliente: 'Cliente B', fecha_pedido: '2026-03-10', estado: 'En proceso', total: 890.75 },
      { id: 1003, cliente: 'Cliente C', fecha_pedido: '2026-03-09', estado: 'Pendiente',  total: 340.00 },
    ],
    productos: [
      { codigo: 'PROD-001', nombre: 'Producto Premium A', categoria: 'Electrónica', precio: 299.99, stock: 45 },
      { codigo: 'PROD-002', nombre: 'Producto Básico B',  categoria: 'Hogar',       precio: 49.99,  stock: 120 },
      { codigo: 'PROD-003', nombre: 'Producto Pro C',     categoria: 'Electrónica', precio: 599.99, stock: 8 },
    ],
    vendedores: [
      { nombre: 'Vendedor 1', zona: 'Norte', meta_mensual: 10000, ventas_mes: 12450.75 },
      { nombre: 'Vendedor 2', zona: 'Sur',   meta_mensual: 8000,  ventas_mes: 7820.00  },
      { nombre: 'Vendedor 3', zona: 'Centro',meta_mensual: 12000, ventas_mes: 14300.50 },
    ]
  };

  // Detectar qué tabla principal menciona el SQL
  let rows = [];
  if      (sqlUpper.includes('PAGOS_PROVEEDORES') || sqlUpper.includes('PROVEEDOR')) {
    rows = mockData.pagos_proveedores;
  } else if (sqlUpper.includes('FACTURAS') || sqlUpper.includes('FACTURA')) {
    rows = mockData.facturas;
  } else if (sqlUpper.includes('PEDIDOS') || sqlUpper.includes('PEDIDO')) {
    rows = mockData.pedidos;
  } else if (sqlUpper.includes('PRODUCTOS') || sqlUpper.includes('PRODUCTO') || sqlUpper.includes('INVENTARIO')) {
    rows = mockData.productos;
  } else if (sqlUpper.includes('VENDEDORES') || sqlUpper.includes('VENDEDOR')) {
    rows = mockData.vendedores;
  } else {
    // Retornar tabla genérica si no se detecta
    rows = [{ mensaje: 'Consulta ejecutada. No se detectaron datos específicos para este query en modo de prueba.' }];
  }

  return [{
    json: {
      success:    true,
      action:     'query',
      tenant:     tenant.name,
      country:    context.country || 'EC',
      sql,
      rows,
      executedIn: `${Math.floor(Math.random() * 80) + 20}ms`
    }
  }];
}

// Action no reconocida
return [{
  json: { success: false, error: `Acción no reconocida: '${action}'. Usa 'schema' o 'query'.` }
}];
